import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse(`{"title":"You're Not Slow. You're Single-Threaded","description":"","frontmatter":{"url":"https://x.com/rohit4verse/status/2059320043478081976","title":"You're Not Slow. You're Single-Threaded","author":"rohit4verse","archived":"2026-05-31T00:00:00.000Z","handle":"@rohit4verse","published":"2026-05-26T00:00:00.000Z","stats":"271 likes · 24 retweets · 1104 bookmarks · 258045 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-26-@rohit4verse-081976.md","filePath":"research/tweets/2026-05-26-@rohit4verse-081976.md","lastUpdated":1780990164000}`),s={name:"research/tweets/2026-05-26-@rohit4verse-081976.md"};function n(i,e,h,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="you-re-not-slow-you-re-single-threaded-—-rohit4verse" tabindex="-1">You&#39;re Not Slow. You&#39;re Single-Threaded — @rohit4verse <a class="header-anchor" href="#you-re-not-slow-you-re-single-threaded-—-rohit4verse" aria-label="Permalink to &quot;You&#39;re Not Slow. You&#39;re Single-Threaded — @rohit4verse&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/rohit4verse/status/2059320043478081976" target="_blank" rel="noreferrer">https://x.com/rohit4verse/status/2059320043478081976</a><strong>作者</strong>：rohit4verse（@rohit4verse） <strong>發布日期</strong>：2026-05-26 <strong>收錄日期</strong>：2026-05-31 <strong>類型</strong>：Twitter Article <strong>統計</strong>：271 likes · 24 retweets · 1104 bookmarks · 258045 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>You designed the product, wrote the code, wrote the launch copy, answered the support tickets, and reconciled the numbers yourself. You did this in order, because one person works one thing at a time. The week you shipped the landing page, the research waited. The week you ran the research, the writing waited.</p><p>Your bottleneck was throughput, and the only person closing the gap is you, working a queue that never empties.</p><p>&quot;Use AI&quot; closed part of the gap. A good model answers at 2 a.m. and never complains. Hand it a real project, though, and it runs the same way you do. It holds one thread and works one step at a time, so the moment a job grows past a single thread, you go back to managing it.</p><p>You cut the work into pieces, feed it the first piece, wait, paste the answer into a doc, then feed it the next piece. The bottleneck shifted onto the handoffs, and the handoffs stayed yours.</p><p>Picture what a second person on your team would change. A second person adds hours. While you draft, they research. While they research, a third builds and a fourth checks the math. Four people turn your one queue into four queues running in the same hour.</p><p>You stay the smartest person in the room while one queue holds you back. Your thinking sets a high ceiling. The single thread sets a much lower one, and the single thread is the one you ship against.</p><p>Stop asking which model scores highest. Ask how you get four queues without hiring four people, and how you keep the speed and low burn of working alone while you borrow the one advantage that used to require a payroll.</p><p>I spent the last few months building that setup for my own work. What follows is the part I wish someone had handed me first.</p><p>[圖 1]</p><h2 id="one-worker-one-line-where-a-single-agent-stalls" tabindex="-1">One worker, one line: where a single agent stalls <a class="header-anchor" href="#one-worker-one-line-where-a-single-agent-stalls" aria-label="Permalink to &quot;One worker, one line: where a single agent stalls&quot;">​</a></h2><p>It works in a straight line</p><p>A single agent reads, plans, acts, checks the result, and plans again. Run a contained task through that cycle and you get what you need.</p><p>The agent stalls when the task runs wide. Take &quot;find fifty companies that fit this thesis, pull their filings, and tell me which five are mispriced.&quot; You wrote one sentence, but you asked for fifty small jobs plus a layer of analysis on top.</p><p>Two things break at scale</p><p>Time fails first. Run fifty independent parts in series and you spend about fifty times what one part costs, even though none of those parts wait on each other.</p><p>Memory fails second. A single context is like a single desk. Pile enough onto it and the early pages slide off the back. By the time the agent reaches company forty, it has lost what it found on company three. The writing keeps its confident tone, and the quality drops underneath.</p><p>Then you become the glue</p><p>When the agent cannot hold the whole job, you fill the gap. You split the work, mark off each finished piece, and carry the results between chats. You manage a project for a machine, which is the work you wanted to escape in the first place.</p><p>A faster model does not fix this</p><p>A sharper single agent still runs one line. You need a different layout: many workers running at once, each with a clean desk, plus one coordinator whose whole job is coordination. Engineers have built that layout for decades. Two things changed. Language models can now do the work, and the system ships to people who never touch infrastructure.</p><h2 id="the-shape-that-fixes-it-a-swarm" tabindex="-1">The shape that fixes it: a swarm <a class="header-anchor" href="#the-shape-that-fixes-it-a-swarm" aria-label="Permalink to &quot;The shape that fixes it: a swarm&quot;">​</a></h2><p>What a swarm does</p><p>In a swarm, one lead agent reads your one-sentence request and splits it into parts that run on their own. The lead agent, called the orchestrator, spawns a crowd of sub-agents, hands each one a slice, runs them in parallel, watches them, and stitches the results back together. You write a sentence. The orchestrator builds a temporary company on the spot, finishes the job, hands you the files, and disbands the crew.</p><p>Where it clicked for me</p><p>I have used several takes on this idea, and Kimi Agent Swarm is the first one I stopped babying. The first three runs I watched like a hawk. On the fourth I stepped away to make coffee, and that was the run that worked. The manager-in-the-middle feeling I had carried for years went quiet after I learned to write the brief and walk off. Kimi Agent Swarm runs as the orchestration mode inside Moonshot AI&#39;s Kimi K2.6, which shipped in April 2026.</p><p>The numbers behind it</p><p>One Kimi run directs up to 300 sub-agents in parallel across 4,000 coordinated steps. The previous version, K2.5, capped at 100 sub-agents and 1,500 steps, so this jump moves you from a small team to a department.</p><p>The 300 workers cover different skills, including search, analysis, coding, long-form writing, and visual generation, and they work those skills at the same time on the same job.</p><p>What lands in your folder</p><p>Kimi reports ceiling outputs in the range of a hundred-plus files, a 100,000-word literature review, or a 20,000-row dataset. My own runs have not touched those ceilings. The biggest sat closer to fifty files and twelve thousand rows. What matters is the shape. You get the work itself, in the formats you would have built by hand, and you stop converting a chat reply into a deliverable. Once that lands, your sense of what one request can return resets, and you start commissioning at the scale of a team.</p><p>[圖 2]</p><h2 id="how-kimi-pulls-it-off" tabindex="-1">How Kimi pulls it off <a class="header-anchor" href="#how-kimi-pulls-it-off" aria-label="Permalink to &quot;How Kimi pulls it off&quot;">​</a></h2><p>Study the mechanism even if you never open Kimi. Each piece maps onto a problem you already feel.</p><p>The orchestrator handles the part you hate</p><p>The lead agent reads your request and breaks it down. It chooses what to run in parallel, how many workers to spawn, what each one needs, and how the pieces fit back together. You write no role descriptions and draw no pipeline. The planning and bookkeeping that used to live between your chats now live inside the system.</p><p>It routes work by skill</p><p>The orchestrator tracks what each sub-agent does well, called a skill profile, and sends each subtask to a matching worker. Research goes to researchers, code to coders, prose to writers. You get specialists for the length of one job, which is the expensive thing you normally cannot afford alone.</p><p>Each worker gets its own memory</p><p>Kimi gives every sub-agent its own memory context and its own toolkit the moment it spawns. The workers share one operational space for what they all need, and each one keeps a private context for its own slice. No single desk holds the whole project, so the early findings never drop off the back.</p><p>It expects workers to fail</p><p>Run 300 workers and some will stall or return garbage. Kimi treats that as routine. The coordinator watches for an agent that hangs or fails, then reassigns or regenerates that subtask. Without that step, one stalled worker would sink the whole run.</p><p>It returns a finished folder</p><p>The orchestrator runs the whole lifecycle. It starts the work, validates it, assembles it, and delivers the artifact. Kimi reports that this parallel approach cuts end-to-end runtime by up to about 80 percent against a single agent, with a measured speedup near 4.5 times. Those are the vendor&#39;s own figures. The point stands either way: a crowd of clean workers finishes a wide job faster than one worker in a line, and keeps more of the quality on the way.</p><h2 id="memory-carries-the-whole-thing" tabindex="-1">Memory carries the whole thing <a class="header-anchor" href="#memory-carries-the-whole-thing" aria-label="Permalink to &quot;Memory carries the whole thing&quot;">​</a></h2><p>I keep coming back to memory. After enough hours watching agents run, the memory design tells me more about whether a job will finish than the model&#39;s intelligence does. When a long job collapses, the failure traces back to memory more often than to reasoning.</p><p>What running out of memory looks like</p><p>You give one agent a big job. It stays sharp through the first stretch. Past the middle, the context fills, the early decisions scroll off the top, and the agent starts arguing with itself. It re-researches a point it settled twenty pages back, then applies a definition on page nine that it rejected on page two. Nothing in the interface flags this. The output degrades while the writing keeps its confident tone.</p><p>How the swarm gets around it</p><p>The swarm never keeps one desk. Kimi gives each worker scoped memory at spawn, sized to its own slice, so no context carries the whole project. The shared space holds only what every worker needs. You decide whether a run holds together by where you put the state, which is why a 4,000-step run stays coherent and a 400-step single thread wanders.</p><p>The lesson, even with one agent</p><p>Design state. Do not assume the model will hold it for you. Decide what each step needs and hand it exactly that. Keep the decisions that must survive the whole job in a small external record, like a running brief or a pinned summary you control. Treat memory as the scarce resource it is.</p><p>[圖 3]</p><h2 id="the-flow-a-solo-builder-can-run" tabindex="-1">The flow a solo builder can run <a class="header-anchor" href="#the-flow-a-solo-builder-can-run" aria-label="Permalink to &quot;The flow a solo builder can run&quot;">​</a></h2><p>Here is the loop I run, step by step. None of it needs a technical background. It needs you to brief a smart contractor well.</p><p>Step 1: Pick a job with the right shape</p><p>Check the shape before you start. A swarm pays off when the job runs wide, splits into independent parts, and ends in real files. Wide and independent fits a swarm. Narrow and deep fits one good agent. If you cannot break the job into parts that run without waiting on each other, hold off and use a single agent.</p><p>Step 2: Brief it like a team</p><p>Most people lose the value here, so take your time. You write a one-page brief, the way you would for a contractor you will never speak to again. Build it in four parts.</p><p>State the role and the goal in a line or two. Name the team and the finished outcome.</p><p>Set the scope and the guardrails. Say where to look, what to include, what to skip, and the hard rules. I always add a line like &quot;use only verifiable sources and invent nothing,&quot; because in a wide research job the model will fill gaps on its own unless you forbid it.</p><p>List the deliverables and number them. Name each artifact you want out the other end, such as a spreadsheet, a written summary, or a set of pages.</p><p>Name the output format. Give the file types and the structure. &quot;A presentation-ready spreadsheet with these columns&quot; beats &quot;give me the data.&quot;</p><p>Step 3: Hand over your raw material</p><p>Drop in everything a new teammate would ask for on day one: your draft, your brand notes, the relevant links, and a few examples of good work. Load it all at once. The swarm reads it in one pass.</p><p>Step 4: Read the plan before you let it run</p><p>The orchestrator lays out how it will split the work before it commits the full crowd. Read that plan the way a manager reads a project outline. You correct course most cheaply right here, before 300 workers run on a misread goal.</p><p>Step 5: Let the swarm work, and watch the checkpoints</p><p>Step back. The workers run in parallel while you do something else. Glance at the progress to confirm the run stays on track. Treat it like a mid-sprint check-in, and stay out of the way between checks.</p><p>Step 6: Take the folder, verify the risky parts</p><p>You open a folder of files. Read it the way an editor reads a draft, and check the parts that carry the most risk first: the numbers and the citations you would hate to get wrong. The swarm works like a fast junior team, so you own the verification, and you skip it at your peril.</p><p>Step 7: Re-run slices, not the whole job</p><p>When a piece comes back weak, re-run that piece. Leave the rest alone. Small, surgical re-runs keep the loop fast.</p><h2 id="a-worked-example" tabindex="-1">A worked example <a class="header-anchor" href="#a-worked-example" aria-label="Permalink to &quot;A worked example&quot;">​</a></h2><p>Say you are about to build a small product and you want to enter the market with your eyes open. Here is the same loop in one pass.</p><p>Shape. &quot;Study thirty competitors&quot; splits into thirty independent jobs plus an analysis layer, so the shape fits.</p><p>Brief. Goal: a competitive map and a positioning angle. Scope: thirty real competitors with live products. Guardrail: verifiable only, no invented features. Deliverables: a comparison spreadsheet, a written teardown, and a one-page positioning recommendation. Format: named columns plus a short document.</p><p>Material. You hand over your own product notes and the competitors you already know.</p><p>Plan. You read its plan and add the two competitors it missed.</p><p>Run. The swarm works the thirty in parallel while you do something else.</p><p>Verify. You open the folder and check the pricing column yourself, because you will quote pricing out loud to investors and customers.</p><p>Re-run. Two teardowns came back thin, so you re-run those two.</p><p>A week of work fits into an afternoon. You spend the afternoon reviewing output the swarm has already built.</p><p>[圖 4]</p><p>[圖 5]</p><p>[圖 6]</p><h2 id="three-jobs-to-hand-it-first" tabindex="-1">Three jobs to hand it first <a class="header-anchor" href="#three-jobs-to-hand-it-first" aria-label="Permalink to &quot;Three jobs to hand it first&quot;">​</a></h2><p>Look for the same shape every time: wide, split into independent parts, ends in files. Point it at one of these on day one.</p><p>Research and writing, in one motion</p><p>You normally research for two days, write for two days, and carry the notes between the two jobs yourself. A swarm collapses that handoff. The research workers read across sources in parallel, the writing workers turn the pooled findings into a draft, and the citations arrive attached because the researchers gathered them. The 100,000-word review sits at the far end of this. Your version runs closer to a 3,000-word post with twenty real sources, finished while you make coffee.</p><p>Build the websites while you do something else</p><p>Take &quot;research thirty local businesses with no web presence and build each one a clean landing page.&quot; You asked for research, design, and code in one sentence. The search workers, the writing workers, and the coding workers run together and hand you a folder of working pages plus a spreadsheet that tracks them. You start treating a website as an output you order. The schedule goes away.</p><p>Research and screening, in parallel</p><p>If your work touches markets or data, this fits best. &quot;Screen 150 companies against this thesis, pull the filings, build the comparison, and flag the outliers&quot; runs wide and independent. A swarm handles it; a single agent drowns in it. Caveat, because this nears money: the swarm assembles evidence faster than you ever could, and it still gets individual facts wrong. Verify before you act on any number.</p><h2 id="think-like-the-orchestrator" tabindex="-1">Think like the orchestrator <a class="header-anchor" href="#think-like-the-orchestrator" aria-label="Permalink to &quot;Think like the orchestrator&quot;">​</a></h2><p>You do not need 300 agents to get most of the gain. You need to drop the worker&#39;s habits and pick up the orchestrator&#39;s. Four habits cover it, and you can run all four today with the tools you already pay for.</p><p>Decompose before you delegate</p><p>Most people hand an agent a fuzzy goal and then fight with it. Break the goal into parts that do not depend on each other first. The question &quot;which pieces of this run independently&quot; turns a two-day slog into a handful of small parallel asks.</p><p>Match the worker to the work</p><p>A specialist beats a generalist on a narrow task. Split the research pass from the writing pass from the checking pass, and run each as its own job with its own clean context.</p><p>Give each job its own memory</p><p>Long single threads rot because everything lands on one desk. Open a fresh, scoped context for each subtask and feed it only what that subtask needs. A single growing chat drags the whole project behind it and forgets the start.</p><p>Plan for failure on purpose</p><p>The swarm routes around stalled workers on its own. You add a checking step to catch the outputs that come back wrong. Builders who design for scale plan for mistakes and build the recovery in from day one.</p><h2 id="where-the-swarm-still-needs-you" tabindex="-1">Where the swarm still needs you <a class="header-anchor" href="#where-the-swarm-still-needs-you" aria-label="Permalink to &quot;Where the swarm still needs you&quot;">​</a></h2><p>I would shortchange you if I sold this as a finished magic trick. Here is the other half.</p><p>Parallelism costs something</p><p>Coordinating 300 workers carries its own overhead, and some jobs do not earn it. Push a short, deep task through a swarm and it runs slower and noisier, because you bolted coordination onto a job that never needed splitting. Reaching for 300 workers on a one-worker job is the new over-engineering.</p><p>The failure you cannot see</p><p>More workers open more places for a quiet error to slip through. Researchers running agent swarms at this scale over long stretches report a familiar pattern. The orchestration impresses early. Over longer runs, the failure modes show up as fast as the wins. Auto-recovery catches the worker that crashes outright. It misses the worker that returns a confident, wrong answer that then flows into the final file. You read the output before it turns into a decision.</p><p>The last ten percent stays yours</p><p>The first time a hundred workers assemble your report, you sit there and watch them work. By the tenth run, you see the seams: the runs that wander, the merges that lose a thread, the deliverable that lands at ninety percent. You own that last ten percent, and the work still asks for your hands and your judgment.</p><h2 id="the-takeaway" tabindex="-1">The takeaway <a class="header-anchor" href="#the-takeaway" aria-label="Permalink to &quot;The takeaway&quot;">​</a></h2><p>You are single-threaded, and that is the constraint. The fix lives in how you operate, and a smarter model will not change it.</p><p>The gain never came from one model growing smart enough to be your whole team. It comes from changing the shape of your work, from a line you walk end to end to a grid that runs at once, and from moving yourself out of the worker&#39;s seat into the orchestrator&#39;s.</p><p>Kimi Agent Swarm is the cleanest version of that shape I have run as one person. The pattern: 300 workers in parallel, each with its own memory and tools, auto-recovery, and a folder of finished files at the end of one sentence. Use it, or use whatever does this best by the time you read this. Vendors turn over every quarter; the shape does not.</p><p>You spent years as the only part of your company that ran at once. You can stop. Learn the flow, hand the wide jobs to the swarm, keep your judgment on the output, and spend the hours you win back on the one job no agent takes from you: deciding what to build.</p><p>Disclosure: I worked with the team behind Kimi on this piece. The opinions, the caveats, and the lines where I tell you to verify the output yourself are mine, and I would not have written any of it if the thing did not do what I described.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：你的瓶頸不是 AI 模型不夠聰明，而是你還在用單執行緒工作——swarm 架構（orchestrator + 300 並行 sub-agent，各有獨立記憶）才能讓一句話變成一整個團隊的交付物，記憶設計比模型智慧更決定任務成敗。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>單執行緒才是真正瓶頸</strong>：換更好的 model 無法解決問題，根本上需要從「一個 worker 走一條線」改成「多個 worker 同時跑一個 grid」</li><li><strong>記憶失敗 &gt; 推理失敗</strong>：長任務崩潰的根本原因是 context 填滿後早期決策靜默消失，輸出品質下降但語氣仍自信——作者的親身觀察</li><li><strong>swarm 的四個設計要點</strong>：skill routing（工作配對 worker 能力）、scoped memory（每個 worker 獨立 context）、failure recovery（自動偵測並重跑失敗 worker）、artifact delivery（輸出完成品而非 chat）</li><li><strong>「形狀判斷」框架</strong>：wide + independent parts + ends in files = 適合 swarm；narrow + deep = 用單一 agent；這是比大多數文章更具體可操作的決策工具</li><li><strong>4 個 orchestrator 習慣</strong>：Decompose before delegate、Match worker to work、Scoped memory per subtask、Plan for failure</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><strong>Kimi Agent Swarm</strong>（Kimi K2.6，Moonshot AI，2026年4月）</li><li><strong>300 sub-agents 並行，4,000 coordinated steps</strong>（K2.5：100/1,500）</li><li><strong>Speedup 4.5x，端到端時間 -80%</strong>（廠商自述數字）</li><li><strong>ceiling outputs</strong>：100,000 字文獻回顧、100+ 檔案、20,000 行資料集；作者實際經驗：50 檔案、12,000 行</li><li><strong>7 步驟工作流</strong>：形狀評估 → brief（角色/範疇/交付物/格式）→ 素材 → 計畫確認 → 執行 → 驗證 → 切片重跑</li><li><strong>3 個第一天適合的任務</strong>：研究+寫作（一次完成）、網站建設、市場/資料篩選</li><li><strong>贊助披露</strong>：作者與 Kimi 團隊合作撰寫</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>贊助內容但誠實披露</strong>：文章末尾明確說明與 Kimi 合作，是業界少見的誠實做法；但仍需考量廠商偏見，speedup 數字為廠商自述</li><li><strong>記憶設計的洞察是全文最有價值的部分</strong>：「context 滿了以後輸出靜默降質但語氣自信」是非常精準的實際觀察，對 MEMORY.md 設計、context-compaction 策略有直接參考價值</li><li><strong>框架的泛化性強於工具本身</strong>：Kimi Agent Swarm 是否最佳不重要，文章的「形狀判斷 + orchestrator 習慣 + 記憶設計」三個框架可套用於任何多 agent 架構（Claude Code subagent-strategy.md 已有類似概念）</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>7步驟工作流 + 形狀判斷框架 + 4個 orchestrator 習慣可立即套用；記憶設計建議直接影響 MEMORY.md 策略</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>orchestrator 思維習慣 + 記憶是稀缺資源的框架有真實洞察；swarm 概念本身不新</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>作者親身使用體驗（50 檔案、12k 行）有可信度；但贊助關係 + speedup 為廠商數字降低客觀性</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>skill routing、scoped memory、auto-recovery 機制描述有深度；記憶失敗模式的分析尤其精準</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>形狀判斷 + orchestrator 習慣 + 記憶設計完全可泛化到任何 multi-agent 架構</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.4/10</strong></td><td>8×0.3+7×0.2+6×0.2+7×0.15+9×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：完整的 solo builder 多 agent 工作流程（7 步驟）+ orchestrator 思維習慣；記憶設計洞察可直接強化現有 subagent-strategy 規則。</p>',134)])])}const w=t(s,[["render",n]]);export{c as __pageData,w as default};
